<?php
/**
 * Sample script for CAPTCHA generation and validation.
 *
 * This is an example file with a simplified implementation of the
 * captcha for demonstration purposes. The actual image is generated by
 * captcha-image.php (SimpleCaptcha itself has no auto-run code).
 *
 * @license MIT
 * @link    https://github.com/aldoexpert/cool-php-captcha
 * @package captcha
 */

session_start();

/** Validate captcha */
$captcha_message = null;
$style            = null;
$request_captcha  = null;

if (!empty($_REQUEST['captcha'])) {
    if (empty($_SESSION['captcha']) || trim(strtolower($_REQUEST['captcha'])) != $_SESSION['captcha']) {
        $captcha_message = "Invalid captcha";
        $style = "background-color: #FF606C";
    } else {
        $captcha_message = "Valid captcha";
        $style = "background-color: #CCFF99";
    }

    $request_captcha = htmlspecialchars($_REQUEST['captcha']);
    unset($_SESSION['captcha']);
}
?>
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="Author" content="Aldo (aldo-expert.com)" />
<title>Captcha test</title>
<style>
body { font-family: sans-serif; font-size: 0.8em; padding: 20px; }
#result { border: 1px solid green; width: 300px; margin: 0 0 35px 0; padding: 10px 20px; font-weight: bold; }
#change-image { font-size: 0.8em; }
</style>
</head>
<body onload="document.getElementById('captcha-form').focus()">

<?php if ($captcha_message): ?>
<div id="result" style="<?=$style?>">
    <h2><?=$captcha_message?></h2>
    <table>
        <tr><td>Session CAPTCHA:</td><td><?=htmlspecialchars((string) ($_SESSION['captcha'] ?? ''))?></td></tr>
        <tr><td>Form CAPTCHA:</td><td><?=$request_captcha?></td></tr>
    </table>
</div>
<?php endif; ?>

<p><strong>Write the following word:</strong></p>

<form method="GET">
    <img src="captcha-image.php" id="captcha" /><br/>

    <!-- CHANGE TEXT LINK -->
    <a href="#" onclick="
        document.getElementById('captcha').src='captcha-image.php?'+Math.random();
        document.getElementById('captcha-form').focus();
        return false;"
        id="change-image">Not readable? Change text.</a><br/><br/>

    <input type="text" name="captcha" id="captcha-form" autocomplete="off" /><br/>
    <input type="submit" />
</form>

</body>
</html>
